mapper.select:
SELECT t.`id` AS `tag_id`, t.`tag_name`, t.`category`, COUNT(active_manga.`id`) AS `tag_count`
FROM `manga_tag` t
LEFT JOIN `manga_tag_relation` r ON r.`tag_id` = t.`id`
LEFT JOIN `manga` active_manga
       ON active_manga.`id` = r.`manga_id`
      AND active_manga.`user_id` = #{userId}
      AND active_manga.`deleted` = #{deleted}
WHERE t.`user_id` = #{userId}

    AND t.`category` = #{category}

GROUP BY t.`id`, t.`tag_name`, t.`category`
ORDER BY `tag_count` DESC, t.`tag_name`, t.`id`
